<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\ExternalSource; use App\Models\ImportBatch; use App\Models\Invoice; use App\Models\SupportTicket; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\View\View;
class AdminOperationsController extends Controller { private function admin(){abort_unless(auth()->user()?->hasRole('super-admin'),403);} public function support():View{$this->admin();return view('admin.special.support',['tickets'=>SupportTicket::with('user')->latest()->get()]);} public function updateSupport(Request $request,SupportTicket $ticket):RedirectResponse{$this->admin();$ticket->update($request->validate(['status'=>'required|in:new,open,in-progress,resolved,closed','priority'=>'required|in:low,normal,high']));return back()->with('success','Ticket updated.');} public function sources():View{$this->admin();return view('admin.special.sources',['sources'=>ExternalSource::latest()->get(),'batches'=>ImportBatch::with('externalSource')->latest()->get()]);} public function storeSource(Request $request):RedirectResponse{$this->admin();ExternalSource::create($request->validate(['name'=>'required|string|max:120','source_type'=>'required|string|max:80','feed_type'=>'required|string|max:80','import_limit'=>'nullable|integer','description'=>'nullable|string'])+['status'=>'active','contacts_visible'=>$request->boolean('contacts_visible')]);return back()->with('success','External source created.');} public function invoices():View{$this->admin();return view('admin.special.invoices',['invoices'=>Invoice::latest()->get()]);} public function export(string $type){$this->admin();$rows=match($type){'companies'=>\App\Models\Company::select('id','name','email','status','country_code')->get(),'candidates'=>\App\Models\User::whereHas('roles',fn($q)=>$q->where('slug','job-seeker'))->select('id','name','email','country_code')->get(),'jobs'=>\App\Models\Job::select('id','title','status','country_code','currency_code')->get(),'applications'=>\App\Models\JobApplication::select('id','job_id','candidate_id','status','match_score')->get(),default=>abort(404)};$filename="lucky-boss-{$type}-".now()->format('YmdHis').'.csv';return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');if($rows->isNotEmpty()){fputcsv($out,array_keys($rows->first()->getAttributes()));foreach($rows as $row){fputcsv($out,$row->getAttributes());}}fclose($out);},$filename,['Content-Type'=>'text/csv']);} }